// =====================================================================
export default function App() {
  const [user, setUser] = useState(null);
  const [orders, setOrders] = useState(seedOrders);

  if (!user) return <Shell><Login onLogin={setUser} /></Shell>;
  if (user.role === "admin")
    return <Shell user={user} onLogout={() => setUser(null)}><Admin orders={orders} setOrders={setOrders} /></Shell>;
  return <Shell user={user} onLogout={() => setUser(null)}><Client user={user} orders={orders} setOrders={setOrders} /></Shell>;
}

/* ---------------------------------- Shell ---------------------------------- */
function Shell({ children, user, onLogout }) {
  return (
    <div style={S.root}>
      <style>{CSS}</style>
      <header style={S.header}>
        <div style={S.brand}><span style={S.mark}>✶</span><span style={S.wordmark}>Memora</span><span style={S.tagline}>ateliê de retratos</span></div>
        {user && (
          <div style={S.headRight}>
            <span style={S.userPill}>{user.role === "admin" ? "Ateliê" : user.cliente?.nome || user.email}</span>
            <button className="ghost sm2" onClick={onLogout}>Sair</button>
          </div>
        )}
      </header>
      <main style={S.main}>{children}</main>
      <footer style={S.footer}>Memora · cada retrato é uma história contada à mão</footer>
    </div>
  );
}

/* ---------------------------------- Login ---------------------------------- */
function Login({ onLogin }) {
  const [mode, setMode] = useState("email");
  const [email, setEmail] = useState("");
  const [sent, setSent] = useState(false);
  const enter = (role) => onLogin({ email: email || "ana@email.com", role, cliente: { nome: "Ana Beatriz" } });

  return (
    <div className="reveal" style={{ maxWidth: 440, margin: "10px auto 0" }}>
      <p style={S.eyebrow}>Sua área no ateliê</p>
      <h1 style={S.h1}>Acompanhe sua <em>obra</em> nascer.</h1>
      <p style={S.lede}>Entre para enviar fotos, escolher um estilo e ver cada etapa da criação.</p>
      <div style={S.card}>
        <div className="tabs">
          <button className={mode === "email" ? "tab on" : "tab"} onClick={() => setMode("email")}>E-mail e senha</button>
          <button className={mode === "code" ? "tab on" : "tab"} onClick={() => setMode("code")}>Código por e-mail</button>
        </div>
        <label className="lbl">E-mail</label>
        <input className="inp" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="voce@email.com" />
        {mode === "email" ? (
          <>
            <label className="lbl">Senha</label>
            <input className="inp" type="password" placeholder="••••••••" />
            <button className="primary block" onClick={() => enter("client")}>Entrar</button>
          </>
        ) : !sent ? (
          <button className="primary block" onClick={() => setSent(true)}>Enviar código</button>
        ) : (
          <>
            <label className="lbl">Código enviado para seu e-mail</label>
            <input className="inp" placeholder="000000" />
            <button className="primary block" onClick={() => enter("client")}>Confirmar e entrar</button>
          </>
        )}
        <button className="google" onClick={() => enter("client")}><b>G</b> Continuar com Google</button>
        <div style={S.adminRow}><button className="ghost sm" onClick={() => enter("admin")}>Entrar como ateliê (admin)</button></div>
      </div>
    </div>
  );
}

/* ---------------------------------- Client ---------------------------------- */
function Client({ user, orders, setOrders }) {
  const [view, setView] = useState({ name: "dash" });
  const mine = orders.filter((o) => o.owner === user.email);

  if (view.name === "new")
    return <NewOrder cliente={user.cliente} onCancel={() => setView({ name: "dash" })}
      onSubmit={(o) => { const cover = o.sujeitos?.[0]?.fotos?.[0] || null; setOrders((p) => [normalize({ ...o, fotos: cover ? [cover] : [], id: uid(), owner: user.email, status: "recebido", date: today() }), ...p]); setView({ name: "dash" }); }} />;

  if (view.name === "detail") {
    const order = orders.find((o) => o.id === view.id);
    return <ClientDetail order={order} back={() => setView({ name: "dash" })}
      update={(patch) => setOrders((p) => p.map((o) => (o.id === order.id ? { ...o, ...patch } : o)))} />;
  }

  return (
    <div className="reveal">
      <div style={S.dashHead}>
        <div><p style={S.eyebrow}>Bem-vinda de volta</p><h1 style={S.h1}>Meu <em>Retrato</em></h1></div>
        <button className="primary" onClick={() => setView({ name: "new" })}>+ Começar um retrato</button>
      </div>
      {mine.length === 0 ? (
        <div style={S.empty}>
          <p style={{ fontSize: 18, fontFamily: SERIF }}>Seu ateliê está em branco.</p>
          <p style={{ color: MUTE, marginTop: 6 }}>Envie uma foto que importa e damos vida a ela.</p>
          <button className="primary" style={{ marginTop: 20 }} onClick={() => setView({ name: "new" })}>Começar um retrato</button>
        </div>
      ) : (
        <div style={S.grid}>{mine.map((o) => <OrderCard key={o.id} o={o} onOpen={() => setView({ name: "detail", id: o.id })} />)}</div>
      )}
    </div>
  );
}

function OrderCard({ o, onOpen }) {
  const st = STATUSES[o.status];
  const style = STYLES.find((s) => s.id === o.estilo);
  return (
    <button className="ordercard" onClick={onOpen}>
      <Frame fill={st.fill} tone={o.fotos[0]?.tone || "#d8c9b4"} src={o.fotos[0]?.src} />
      <div style={{ padding: "16px 18px 18px" }}>
        <div style={S.cardTop}><span style={S.orderNo}>#{o.id}</span><StatusTag status={o.status} /></div>
        <p style={S.cardPara}>{style?.name || "Retrato personalizado"}</p>
        <p style={S.cardMeta}>{fmtFormato(o) || "Formato a definir"} · {o.date}</p>
        <span className="link">Ver detalhes →</span>
      </div>
    </button>
  );
}

/* ----------------------- Novo pedido — 5 fases ----------------------- */
const LOCAIS = ["Sala de estar", "Quarto", "Escritório", "Entrada / hall", "Cozinha", "Ainda não sei"];
const DESTINOS = ["Minha mãe", "Meu pai", "Minha avó", "Meu avô", "Meu irmão", "Minha irmã", "Meu filho", "Minha filha", "Meu namorado", "Minha namorada", "Meu marido", "Minha esposa", "Meu amigo", "Minha amiga", "Meu pet", "Minha família"];
const ORIENTACOES = [
  { id: "retrato", name: "Retrato", ratio: "3 / 4" },
  { id: "paisagem", name: "Paisagem", ratio: "4 / 3" },
  { id: "quadrado", name: "Quadrado", ratio: "1 / 1" },
];
const TAMANHOS = {
  retrato:  [{ id: "a4", name: "A4", cm: "21 × 30 cm" }, { id: "a3", name: "A3", cm: "30 × 42 cm" }, { id: "4060", name: "Médio", cm: "40 × 60 cm" }, { id: "6090", name: "Grande", cm: "60 × 90 cm" }],
  paisagem: [{ id: "a4", name: "A4", cm: "30 × 21 cm" }, { id: "a3", name: "A3", cm: "42 × 30 cm" }, { id: "6040", name: "Médio", cm: "60 × 40 cm" }, { id: "9060", name: "Grande", cm: "90 × 60 cm" }],
  quadrado: [{ id: "30", name: "Pequeno", cm: "30 × 30 cm" }, { id: "40", name: "Médio", cm: "40 × 40 cm" }, { id: "60", name: "Grande", cm: "60 × 60 cm" }, { id: "80", name: "Extra", cm: "80 × 80 cm" }],
};

function NewOrder({ onSubmit, onCancel, cliente }) {
  const [phase, setPhase] = useState(1);
  const [f, setF] = useState(normalize({
    cliente: { nome: cliente?.nome || "", nascimento: "", whatsapp: "", email: "" },
    sujeitos: [{ id: uid(), quem: "", fotos: [], fotosSecundarias: [] }],
  }));
  const set = (patch) => setF((p) => ({ ...p, ...patch }));
  const setC = (k, v) => setF((p) => ({ ...p, cliente: { ...p.cliente, [k]: v } }));
  const toggleTom = (id) => set({ tons: f.tons.includes(id) ? f.tons.filter((t) => t !== id) : [...f.tons, id] });
  const setSujeitosCount = (n) => setF((p) => {
    const arr = [...p.sujeitos];
    while (arr.length < n) arr.push({ id: uid(), quem: "", fotos: [], fotosSecundarias: [] });
    return { ...p, sujeitos: arr.slice(0, n) };
  });
  const updateSujeito = (id, patch) => setF((p) => ({ ...p, sujeitos: p.sujeitos.map((s) => (s.id === id ? { ...s, ...patch } : s)) }));

  const phases = ["Sobre você", "O formato", "As fotos", "O estilo"];
  const canNext = {
    1: f.cliente.nome && f.cliente.email,
    2: f.orientacao && f.tamanho,
    3: f.sujeitos.every((s) => s.fotos.length > 0),
    4: f.estilo,
  }[phase];

  return (
    <div className="reveal" style={{ maxWidth: 720, margin: "0 auto" }}>
      <button className="ghost sm" onClick={onCancel}>← Voltar</button>
      <p style={S.eyebrow}>Novo retrato · etapa {phase} de 4</p>
      <h1 style={S.h1}>{phaseTitle(phase)}</h1>
      <Stepper steps={phases} step={phase - 1} />

      <div style={S.card}>
        {phase === 1 && (
          <>
            <p style={S.fieldHint}>Para começarmos a te conhecer.</p>
            <Field label="Nome completo"><input className="inp" value={f.cliente.nome} onChange={(e) => setC("nome", e.target.value)} placeholder="Seu nome" /></Field>
            <Field label="Data de nascimento"><input className="inp" type="date" value={f.cliente.nascimento} onChange={(e) => setC("nascimento", e.target.value)} /></Field>
            <Field label="WhatsApp"><input className="inp" value={f.cliente.whatsapp} onChange={(e) => setC("whatsapp", e.target.value)} placeholder="(00) 00000-0000" /></Field>
            <Field label="E-mail"><input className="inp" value={f.cliente.email} onChange={(e) => setC("email", e.target.value)} placeholder="voce@email.com" /></Field>
          </>
        )}

        {phase === 2 && (
          <>
            <Field label="Orientação do quadro">
              <div style={S.orientRow}>
                {ORIENTACOES.map((o) => (
                  <button key={o.id} className={f.orientacao === o.id ? "orient on" : "orient"} onClick={() => set({ orientacao: o.id, tamanho: "" })}>
                    <span style={S.orientIconBox}><span style={{ ...S.orientShape, aspectRatio: o.ratio }} /></span>
                    <span style={S.orientName}>{o.name}</span>
                  </button>
                ))}
              </div>
            </Field>

            {f.orientacao && (
              <Field label="Tamanho">
                <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                  {TAMANHOS[f.orientacao].map((t) => (
                    <button key={t.id} className={f.tamanho === t.id ? "sizechip on" : "sizechip"} onClick={() => set({ tamanho: t.id, tamanhoOutro: "" })}>
                      <strong>{t.name}</strong><span>{t.cm}</span>
                    </button>
                  ))}
                  <button className={f.tamanho === "outro" ? "sizechip on" : "sizechip"} onClick={() => set({ tamanho: "outro" })}>
                    <strong>Outro</strong><span>medida sob medida</span>
                  </button>
                </div>
                {f.tamanho === "outro" && (
                  <input className="inp" style={{ marginTop: 10 }} value={f.tamanhoOutro} onChange={(e) => set({ tamanhoOutro: e.target.value })}
                    placeholder="Escreva o tamanho desejado — ex.: 50 × 70 cm" />
                )}
              </Field>
            )}
          </>
        )}

        {phase === 3 && (
          <>
            <p style={S.fieldHint}>Quem vai aparecer no quadro? Se as pessoas (ou pets) não têm uma foto juntos, tudo bem — envie as fotos separadas e nós montamos a cena.</p>

            <Field label="Quantos vão aparecer no retrato?">
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                {[1, 2, 3, 4].map((n) => (
                  <button key={n} className={f.sujeitos.length === n ? "chip on" : "chip"} onClick={() => setSujeitosCount(n)}>
                    {n === 1 ? "Só uma pessoa" : `${n} ${n === 4 ? "ou mais" : ""}`.trim()}
                  </button>
                ))}
              </div>
            </Field>

            {f.sujeitos.map((s, i) => (
              <div key={s.id} style={S.subjectCard}>
                <div style={S.subjectHead}>
                  <span style={S.subjectNum}>{i + 1}</span>
                  <input className="inp" style={{ flex: 1 }} value={s.quem} onChange={(e) => updateSujeito(s.id, { quem: e.target.value })}
                    placeholder={i === 0 ? "Quem é? ex.: Você, eu mesma…" : "Quem é? ex.: meu cachorro, meu namorado…"} />
                </div>
                <label className="lbl" style={{ marginTop: 14 }}>Foto principal {s.quem ? `de ${s.quem}` : ""}</label>
                <Uploader items={s.fotos} max={1} onChange={(fotos) => updateSujeito(s.id, { fotos })} hint="O rosto que vira obra" big />
                <label className="lbl" style={{ marginTop: 14 }}>Outros ângulos (opcional, até 2)</label>
                <Uploader items={s.fotosSecundarias} max={2} onChange={(fotosSecundarias) => updateSujeito(s.id, { fotosSecundarias })} hint="Mais ângulos do rosto" />
              </div>
            ))}
            <p style={S.microHint}>Mais ângulos ajudam o artista a captar melhor as feições de cada um.</p>
          </>
        )}

        {phase === 4 && (
          <>
            <Field label="1 · Tipo de pintura — qual acabamento de pincel e tinta te encanta?">
              <div style={S.artGrid}>
                {STYLES.map((s) => (
                  <button key={s.id} className={f.estilo === s.id ? "painttype on" : "painttype"} onClick={() => set({ estilo: s.id })}>
                    <img src={s.img} alt={s.name} style={S.artImg} />
                    <div className="ptbody">
                      <strong>{s.name}</strong><span>{s.desc}</span>
                      <div className="ptbrush" style={{ backgroundImage: `url(${s.brush})` }} aria-hidden="true" />
                    </div>
                  </button>
                ))}
              </div>
            </Field>

            <Field label="2 · Estilo artístico — conjunto de técnicas, temas e formas que caracterizam a produção">
              <div style={S.artGrid}>
                {ARTISTICOS.map((a) => (
                  <button key={a.id} className={f.artistico === a.id ? "artcard on" : "artcard"} onClick={() => set({ artistico: a.id })}>
                    <img src={a.img} alt={a.name} style={S.artImg} />
                    <strong>{a.name}</strong><span>{a.desc}</span>
                  </button>
                ))}
              </div>
            </Field>

            <Field label="3 · Universo da imagem — o que envolve a pessoa">
              <div style={S.artGrid}>
                {CENARIOS.map((c) => (
                  <button key={c.id} className={f.cenario === c.id ? "artcard sm on" : "artcard sm"} onClick={() => set({ cenario: c.id })}>
                    <ArtSample kind={c.art} />
                    <strong>{c.name}</strong>
                  </button>
                ))}
              </div>
            </Field>

            <Field label="4 · Personalidade — o que a obra deve transmitir? (pode escolher várias)">
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                {PERSONALIDADES.map((p) => (
                  <button key={p.id} className={f.personalidades.includes(p.id) ? "chip on" : "chip"}
                    onClick={() => set({ personalidades: f.personalidades.includes(p.id) ? f.personalidades.filter((x) => x !== p.id) : [...f.personalidades, p.id] })}>
                    {p.name}
                  </button>
                ))}
              </div>
            </Field>

            <Field label="Quais tons você imagina?">
              <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                {TONS.map((t) => (
                  <button key={t.id} className={f.tons.includes(t.id) ? "tonchip on" : "tonchip"} onClick={() => toggleTom(t.id)}>
                    <span style={S.tonDots}>{t.colors.map((c, i) => <i key={i} style={{ background: c }} />)}</span>{t.name}
                  </button>
                ))}
              </div>
            </Field>

            <Field label="Selecione na galeria até 3 inspirações que você ama">
              <InspiracoesGaleria selected={f.inspiracoes} onChange={(inspiracoes) => set({ inspiracoes })} />
            </Field>

            <Field label="Tem mais algo que gostaria de incluir no seu quadro?">
              <textarea className="inp ta" value={f.extra} onChange={(e) => set({ extra: e.target.value })}
                placeholder="Uma frase, um nome, um objeto especial, o seu pet, um livro, um elemento essencial para você…" />
              <p style={S.microHint}>Esse quadro deve refletir quem a pessoa é, o que sente e o que sonha.</p>
            </Field>
          </>
        )}

        <div style={S.wizardNav}>
          {phase > 1 ? <button className="ghost" onClick={() => setPhase(phase - 1)}>Anterior</button> : <span />}
          {phase < 4
            ? <button className="primary" disabled={!canNext} onClick={() => setPhase(phase + 1)}>Continuar</button>
            : <button className="primary lg" disabled={!canNext} onClick={() => onSubmit(f)}>Enviar para o ateliê</button>}
        </div>
      </div>
    </div>
  );
}
function phaseTitle(p) {
  return ["", "Sobre você", "Formato do quadro", "Suas fotos", "O estilo da obra"][p];
}

/* ---------------------------------- Client detail ---------------------------------- */
function ClientDetail({ order, back, update }) {
  const [pick, setPick] = useState(order.escolha);
  const [ajuste, setAjuste] = useState("");
  const st = STATUSES[order.status];
  const style = STYLES.find((s) => s.id === order.estilo);

  return (
    <div className="reveal" style={{ maxWidth: 820, margin: "0 auto" }}>
      <button className="ghost sm" onClick={back}>← Meus retratos</button>
      <div style={S.detailHead}>
        <div><p style={S.eyebrow}>Pedido #{order.id} · {order.date}</p><h1 style={S.h1}>Seu retrato</h1></div>
        <StatusTag status={order.status} big />
      </div>
      <ProgressRail status={order.status} />
      <p style={S.statusHint}>{st.hint}</p>

      {order.mensagens.length > 0 && (
        <section style={S.card}>
          <h2 style={S.h2}>Recado do ateliê</h2>
          {order.mensagens.map((m) => (
            <div key={m.id} style={S.msg}><div style={S.msgHead}><span>{m.de === "ateliê" ? "✦ Ateliê Memora" : "Você"}</span><span style={{ color: MUTE }}>{m.data}</span></div><p style={{ margin: "6px 0 0" }}>{m.texto}</p></div>
          ))}
        </section>
      )}

      {order.status === "aprovacao" && (
        <section style={S.card}>
          <h2 style={S.h2}>Escolha sua versão favorita</h2>
          <div style={S.versionGrid}>
            {order.versoes.map((v, i) => (
              <button key={v.id} className={pick === i ? "version on" : "version"} onClick={() => setPick(i)}>
                <div style={{ ...S.bigArt, background: v.src ? `center/cover no-repeat url(${v.src})` : artGradient(v.tone) }}>{pick === i && <span style={S.check}>✓</span>}</div>
                <strong>{v.nome}</strong>{v.obs && <span style={{ color: MUTE, fontSize: 13 }}>{v.obs}</span>}
              </button>
            ))}
          </div>
          <button className="primary lg" style={{ marginTop: 18 }} disabled={pick === null}
            onClick={() => update({ escolha: pick, status: "finalizado", final: { tone: order.versoes[pick].tone } })}>
            Aprovar versão {pick !== null ? pick + 1 : ""}
          </button>
          <div style={S.divider} />
          <label className="lbl">Prefere ajustar algo antes?</label>
          <textarea className="inp ta" value={ajuste} onChange={(e) => setAjuste(e.target.value)} placeholder="Menos flores · mais claro · trocar cores · centralizar rosto" />
          <button className="ghost" style={{ marginTop: 10 }} disabled={!ajuste.trim()}
            onClick={() => update({ status: "ajustes", ajusteTexto: ajuste, mensagens: [...order.mensagens, { id: uid(), de: "cliente", texto: ajuste, data: today().slice(0, 6) }] })}>Solicitar ajustes</button>
        </section>
      )}

      {order.status === "finalizado" && order.final && (
        <section style={S.card}>
          <h2 style={S.h2}>Sua obra está pronta.</h2>
          <div style={{ ...S.bigArt, background: artGradient(order.final.tone), height: 340, marginBottom: 22, aspectRatio: ratioOf(order.orientacao) }} />
          <h3 style={S.h3}>Veja na parede</h3>
          <RoomMockup tone={order.final.tone} orientacao={order.orientacao} />
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 18 }}>
            <button className="primary">Baixar JPG</button><button className="ghost">Baixar PNG</button><button className="ghost">Baixar PDF</button>
          </div>
        </section>
      )}

      {order.status === "ajustes" && (
        <section style={S.card}><h2 style={S.h2}>Estamos refinando</h2><p style={{ color: MUTE }}>Seu pedido de ajuste:</p><blockquote style={S.quote}>{order.ajusteTexto}</blockquote></section>
      )}

      <ResumoPedido order={order} style={style} />
    </div>
  );
}

function ResumoPedido({ order, style }) {
  return (
    <section style={S.card}>
      <h2 style={S.h2}>Resumo do pedido</h2>
      <Detail k="Tipo de pintura" v={style?.name} />
      <Detail k="Estilo artístico" v={nameOf(ARTISTICOS, order.artistico)} />
      <Detail k="Universo" v={nameOf(CENARIOS, order.cenario)} />
      <Detail k="Personalidade" v={fmtPersonalidades(order.personalidades)} />
      <Detail k="Formato" v={fmtFormato(order)} />
      <Detail k="Tons" v={order.tons.map((t) => TONS.find((x) => x.id === t)?.name).filter(Boolean).join(", ")} />
      {order.extra && <Detail k="Pedido especial" v={order.extra} />}
      {order.inspiracoes.length > 0 && <div style={{ marginTop: 12 }}><p style={S.subjLabel}>Inspirações escolhidas</p><div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>{order.inspiracoes.map((id) => { const g = GALERIA.find((x) => x.id === id); return <div key={id} style={{ ...S.thumb, width: 64, height: 64, overflow: "hidden" }}><ArtSample kind={g?.art} /></div>; })}</div></div>}
      <SubjectPhotos order={order} />
      {order.referencias.length > 0 && <div style={{ display: "flex", gap: 10, marginTop: 12, flexWrap: "wrap" }}>{order.referencias.map((p) => <Thumb key={p.id} tone={p.tone} src={p.src} ref_ />)}</div>}
    </section>
  );
}

/* ---------------------------------- Admin ---------------------------------- */
function Admin({ orders, setOrders }) {
  const [filter, setFilter] = useState("todos");
  const [openId, setOpenId] = useState(null);
  const counts = useMemo(() => {
    const c = { todos: orders.length }; STATUS_ORDER.forEach((s) => (c[s] = orders.filter((o) => o.status === s).length)); return c;
  }, [orders]);

  if (openId != null) {
    const order = orders.find((o) => o.id === openId);
    if (!order) { setOpenId(null); return null; }
    return <AdminDetail order={order} back={() => setOpenId(null)}
      update={(patch) => setOrders((p) => p.map((o) => (o.id === order.id ? { ...o, ...patch } : o)))} />;
  }
  const list = filter === "todos" ? orders : orders.filter((o) => o.status === filter);
  return (
    <div className="reveal">
      <p style={S.eyebrow}>Ateliê</p><h1 style={S.h1}>Todos os <em>pedidos</em></h1>
      <div className="filters">
        <button className={filter === "todos" ? "filt on" : "filt"} onClick={() => setFilter("todos")}>Todos <i>{counts.todos}</i></button>
        {STATUS_ORDER.map((s) => <button key={s} className={filter === s ? "filt on" : "filt"} onClick={() => setFilter(s)}>{STATUSES[s].label} <i>{counts[s]}</i></button>)}
      </div>
      <table style={S.table}>
        <thead><tr><th>Pedido</th><th>Cliente</th><th>Formato</th><th>Estilo</th><th>Data</th><th>Status</th><th></th></tr></thead>
        <tbody>
          {list.map((o) => (
            <tr key={o.id} className="trow">
              <td><strong>#{o.id}</strong></td><td>{o.cliente.nome}</td><td>{fmtFormato(o) || "—"}</td>
              <td>{STYLES.find((s) => s.id === o.estilo)?.name || "—"}</td><td style={{ color: MUTE }}>{o.date}</td>
              <td><StatusTag status={o.status} /></td><td><button className="ghost sm2" onClick={() => setOpenId(o.id)}>Abrir</button></td>
            </tr>
          ))}
        </tbody>
      </table>
      {list.length === 0 && <p style={{ color: MUTE, marginTop: 20 }}>Nenhum pedido neste filtro.</p>}
    </div>
  );
}

function AdminDetail({ order, back, update }) {
  const style = STYLES.find((s) => s.id === order.estilo);
  const v = order.versoes;
  const [v1, setV1] = useState(v[0]?.nome || "Versão mais vibrante");
  const [v1obs, setV1obs] = useState(v[0]?.obs || "");
  const [v1img, setV1img] = useState(v[0]?.src || null);
  const [v2, setV2] = useState(v[1]?.nome || "Versão mais clássica");
  const [v2obs, setV2obs] = useState(v[1]?.obs || "");
  const [v2img, setV2img] = useState(v[1]?.src || null);
  const [finalImg, setFinalImg] = useState(order.final?.src || null);

  const NOTIFICACOES = [
    { id: "recebido", label: "Pedido recebido", assunto: "Recebemos seu pedido ✦ Ateliê Memora", corpo: "Olá! Recebemos seu pedido e já estamos analisando cada detalhe com carinho. Em breve daremos início à produção." },
    { id: "producao", label: "Em produção", assunto: "Seu retrato entrou em produção ✦ Ateliê Memora", corpo: "Boa notícia! Seu retrato acaba de entrar em produção. Logo te enviaremos duas versões para você escolher a favorita." },
    { id: "ajustes", label: "Ajustes em andamento", assunto: "Estamos refinando seu retrato ✦ Ateliê Memora", corpo: "Recebemos seu pedido de ajuste e já estamos trabalhando nas alterações. Em breve te mostraremos o resultado." },
    { id: "atraso", label: "Aviso de prazo", assunto: "Atualização sobre o prazo ✦ Ateliê Memora", corpo: "Queremos te avisar que precisaremos de alguns dias extras para entregar seu retrato com a qualidade que merece." },
  ];
  const [notifTipo, setNotifTipo] = useState("producao");
  const [notifCorpo, setNotifCorpo] = useState(NOTIFICACOES[1].corpo);
  const escolherNotif = (id) => {
    const n = NOTIFICACOES.find((x) => x.id === id);
    setNotifTipo(id);
    setNotifCorpo(n.corpo);
  };

  const mailto = (assunto, corpo) => {
    const email = (order.cliente.email || "").trim();
    if (!email) { alert("E-mail da cliente não preenchido."); return; }
    const url = `mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent(assunto)}&body=${encodeURIComponent(corpo)}`;
    window.location.href = url;
  };

  const enviarNotificacao = () => {
    const n = NOTIFICACOES.find((x) => x.id === notifTipo);
    mailto(n.assunto, `${notifCorpo}\n\nPedido #${order.id} — ${order.cliente.nome}\n\nCom carinho,\nAteliê Memora`);
    if (notifTipo === "producao") update({ status: "producao" });
    if (notifTipo === "ajustes") update({ status: "ajustes" });
  };

  const sendVersions = () => {
    if (!v1img || !v2img) { alert("Faça o upload das duas imagens antes de enviar."); return; }
    update({
      status: "aprovacao",
      versoes: [
        { id: uid(), nome: v1, obs: v1obs, tone: "#e7c9a0", src: v1img },
        { id: uid(), nome: v2, obs: v2obs, tone: "#cdbfa6", src: v2img },
      ],
    });
    const corpo = `Olá ${order.cliente.nome.split(" ")[0] || ""}!\n\nSuas duas versões estão prontas para aprovação. Acesse sua área no Ateliê Memora para ver e escolher a favorita.\n\nPedido #${order.id}\n\nCom carinho,\nAteliê Memora`;
    mailto("Suas versões estão prontas ✦ Ateliê Memora", corpo);
  };

  const sendFinal = () => {
    if (!finalImg) { alert("Faça o upload do arquivo final antes de enviar."); return; }
    update({ status: "finalizado", final: { tone: order.versoes[order.escolha ?? 0]?.tone || "#e4cba2", src: finalImg } });
    const corpo = `Olá ${order.cliente.nome.split(" ")[0] || ""}!\n\nSeu retrato está pronto. Acesse sua área no Ateliê Memora para baixar o arquivo final em alta qualidade.\n\nPedido #${order.id}\n\nCom carinho,\nAteliê Memora`;
    mailto("Sua obra está pronta ✦ Ateliê Memora", corpo);
  };

  return (
    <div className="reveal" style={{ maxWidth: 940, margin: "0 auto" }}>
      <button className="ghost sm" onClick={back}>← Todos os pedidos</button>
      <div style={S.detailHead}><div><p style={S.eyebrow}>Pedido #{order.id} · {order.date}</p><h1 style={S.h1}>{order.cliente.nome}</h1></div><StatusTag status={order.status} big /></div>

      <div style={S.adminCols}>
        {/* COLUNA 1 — tudo do cliente */}
        <div>
          <section style={S.card}>
            <h2 style={S.h2}>Dados do cliente</h2>
            <Detail k="Nome" v={order.cliente.nome} />
            <Detail k="Nascimento" v={fmtDate(order.cliente.nascimento)} />
            <Detail k="WhatsApp" v={order.cliente.whatsapp} />
            <Detail k="E-mail" v={order.cliente.email} />
          </section>

          <section style={S.card}>
            <h2 style={S.h2}>O retrato</h2>
            <Detail k="Tipo de pintura" v={style?.name} />
            <Detail k="Estilo artístico" v={nameOf(ARTISTICOS, order.artistico)} />
            <Detail k="Universo" v={nameOf(CENARIOS, order.cenario)} />
            <Detail k="Personalidade" v={fmtPersonalidades(order.personalidades)} />
            <Detail k="Formato" v={fmtFormato(order)} />
            <Detail k="Tons" v={order.tons.map((t) => TONS.find((x) => x.id === t)?.name).filter(Boolean).join(", ")} />
            {order.extra && <Detail k="Pedido especial" v={order.extra} />}
            {order.ajusteTexto && <><div style={S.divider} /><Detail k="Ajuste pedido" v={order.ajusteTexto} /></>}

            {order.inspiracoes.length > 0 && <><h3 style={S.h3}>Inspirações escolhidas</h3><div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>{order.inspiracoes.map((id) => { const g = GALERIA.find((x) => x.id === id); return <div key={id} style={{ ...S.thumb, width: 70, height: 70, overflow: "hidden" }}><ArtSample kind={g?.art} /></div>; })}</div></>}
            <h3 style={S.h3}>Fotos enviadas</h3>
            <SubjectPhotos order={order} big />
            {order.referencias.length > 0 && <><h3 style={S.h3}>Referências enviadas</h3><div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>{order.referencias.map((p) => <Thumb key={p.id} tone={p.tone} src={p.src} ref_ />)}</div></>}
          </section>
        </div>

        {/* COLUNA 2 — ações do ateliê */}
        <div>
          <section style={S.card}>
            <h2 style={S.h2}>Notificar cliente por e-mail</h2>
            <p style={{ color: MUTE, fontSize: 13, marginTop: -4 }}>
              Envia direto para <strong>{order.cliente.email || "—"}</strong> abrindo seu cliente de e-mail.
            </p>
            <label className="lbl" style={{ marginTop: 12 }}>Mensagem automática</label>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
              {NOTIFICACOES.map((n) => (
                <button key={n.id} className={notifTipo === n.id ? "chip on" : "chip"} onClick={() => escolherNotif(n.id)}>{n.label}</button>
              ))}
            </div>
            <textarea className="inp ta" value={notifCorpo} onChange={(e) => setNotifCorpo(e.target.value)} rows={5} />
            <button className="primary block" style={{ marginTop: 10 }} onClick={enviarNotificacao}>
              ✉ Enviar e-mail à cliente
            </button>
          </section>

          <section style={S.card}>
            <h2 style={S.h2}>Fluxo do pedido</h2>
            <button className="ghost block" onClick={() => update({ status: "producao" })}>Marcar "Em produção"</button>

            <div style={S.divider} />
            <h3 style={S.h3}>Subir 2 versões para a cliente escolher</h3>

            <label className="lbl">Versão 1 — nome</label>
            <input className="inp" value={v1} onChange={(e) => setV1(e.target.value)} />
            <UploadOne label="Imagem da versão 1" value={v1img} onChange={setV1img} />
            <input className="inp" style={{ marginTop: 8 }} value={v1obs} onChange={(e) => setV1obs(e.target.value)} placeholder="Observação (ex.: mais vibrante)" />

            <label className="lbl" style={{ marginTop: 14 }}>Versão 2 — nome</label>
            <input className="inp" value={v2} onChange={(e) => setV2(e.target.value)} />
            <UploadOne label="Imagem da versão 2" value={v2img} onChange={setV2img} />
            <input className="inp" style={{ marginTop: 8 }} value={v2obs} onChange={(e) => setV2obs(e.target.value)} placeholder="Observação (ex.: mais clássica)" />

            <button className="primary block" style={{ marginTop: 14 }} onClick={sendVersions}>
              ✉ Enviar versões para aprovação (por e-mail)
            </button>

            <div style={S.divider} />
            <h3 style={S.h3}>Entrega final</h3>
            <UploadOne label="Arquivo final aprovado" value={finalImg} onChange={setFinalImg} />
            <p style={S.microHint}>Pré-visualização aplicada na parede (a cliente verá assim):</p>
            <div style={{ marginTop: 10 }}><RoomMockup tone={order.versoes[order.escolha ?? 0]?.tone || "#e4cba2"} orientacao={order.orientacao} /></div>
            <button className="primary block" style={{ marginTop: 14 }} onClick={sendFinal}>✉ Enviar arquivo final à cliente</button>
          </section>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------- Pieces ---------------------------------- */
// Miniaturas ilustrativas (SVG gerado) que evocam cada técnica/cenário — sem usar obras reais.
function ArtSample({ kind }) {
  const face = (fill, stroke) => (
    <g>
      <circle cx="50" cy="42" r="16" fill={fill} />
      <path d="M30 78 Q50 58 70 78 L70 84 L30 84 Z" fill={fill} />
      {stroke && <><circle cx="50" cy="42" r="16" fill="none" stroke={stroke} strokeWidth="1.5" /><path d="M30 78 Q50 58 70 78" fill="none" stroke={stroke} strokeWidth="1.5" /></>}
    </g>
  );
  const A = { width: "100%", height: 84, viewBox: "0 0 100 84", preserveAspectRatio: "xMidYMid slice", style: { display: "block", borderRadius: "6px 6px 0 0" } };
  switch (kind) {
    case "aquarela": return <svg {...A}><rect width="100" height="84" fill="#f3eee6"/><circle cx="38" cy="34" r="26" fill="#cfe0e6" opacity=".7"/><circle cx="64" cy="48" r="22" fill="#e8cdbf" opacity=".7"/><circle cx="52" cy="30" r="18" fill="#dfe6cf" opacity=".6"/>{face("#b98e74")}</svg>;
    case "acrilica": return <svg {...A}><rect width="100" height="84" fill="#efe7da"/><rect x="10" y="14" width="80" height="18" fill="#d98a4e" opacity=".8"/><rect x="14" y="50" width="72" height="16" fill="#3f8a7a" opacity=".75"/>{face("#8a5a3a")}</svg>;
    case "oleo": return <svg {...A}><rect width="100" height="84" fill="#2b2620"/><ellipse cx="50" cy="44" rx="34" ry="32" fill="#5a4630"/>{face("#c89a6a")}</svg>;
    case "sketch": return <svg {...A}><rect width="100" height="84" fill="#fbfaf6"/><g fill="none" stroke="#3b352c" strokeWidth="1.4"><circle cx="50" cy="40" r="16"/><path d="M32 80 Q50 60 68 80"/><path d="M40 38 q4 4 8 0"/></g></svg>;
    case "popart": return <svg {...A}><rect width="50" height="42" fill="#f6c026"/><rect x="50" width="50" height="42" fill="#e0517a"/><rect y="42" width="50" height="42" fill="#3f9ad8"/><rect x="50" y="42" width="50" height="42" fill="#5db06a"/>{face("#2b2620")}</svg>;
    case "street": return <svg {...A}><rect width="100" height="84" fill="#3a3a3c"/><path d="M0 60 L100 40" stroke="#e0517a" strokeWidth="8"/><path d="M0 30 L100 70" stroke="#f6c026" strokeWidth="6" opacity=".8"/>{face("#d8c4a8")}</svg>;
    case "colagem": return <svg {...A}><rect width="100" height="84" fill="#ece5d8"/><rect x="8" y="10" width="40" height="36" fill="#c9a87c" transform="rotate(-6 28 28)"/><rect x="52" y="30" width="38" height="44" fill="#9ab0a0" transform="rotate(5 71 52)"/>{face("#6f5a3e")}</svg>;
    case "digital": return <svg {...A}><defs><linearGradient id="dg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#b59cc4"/><stop offset="1" stopColor="#e8c7b0"/></linearGradient></defs><rect width="100" height="84" fill="url(#dg)"/>{face("#7a5c6a", "#fff")}</svg>;
    // cenários
    case "flores": return <svg {...A}><rect width="100" height="84" fill="#f3eee6"/>{[ [16,20,"#e0517a"],[80,26,"#f0a02a"],[24,64,"#c97b9a"],[78,66,"#e9b04a"] ].map(([x,y,c],i)=><g key={i}>{[0,72,144,216,288].map(a=><ellipse key={a} cx={x} cy={y} rx="6" ry="3" fill={c} transform={`rotate(${a} ${x} ${y})`}/>)}</g>)}{face("#b98e74")}</svg>;
    case "jardim": return <svg {...A}><rect width="100" height="84" fill="#eaf0e2"/><path d="M0 84 Q20 60 30 84 M70 84 Q82 58 100 84" fill="#7d9471"/>{[14,86].map(x=><path key={x} d={`M${x} 80 q-6 -16 0 -28`} stroke="#5d7a5a" strokeWidth="3" fill="none"/>)}{face("#b98e74")}</svg>;
    case "sonhador": return <svg {...A}><defs><linearGradient id="sk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#3a4a72"/><stop offset="1" stopColor="#b59cc4"/></linearGradient></defs><rect width="100" height="84" fill="url(#sk)"/>{[ [18,16],[30,28],[78,18],[86,40],[60,12] ].map(([x,y],i)=><circle key={i} cx={x} cy={y} r="1.6" fill="#fff"/>)}<circle cx="74" cy="60" r="10" fill="#f4e6c4" opacity=".5"/>{face("#d8c4a8")}</svg>;
    case "borboletas": return <svg {...A}><rect width="100" height="84" fill="#f5eef0"/>{[[20,22,"#c97b9a"],[82,30,"#9ab0c4"]].map(([x,y,c],i)=><g key={i} fill={c} opacity=".85"><ellipse cx={x-4} cy={y} rx="4" ry="6"/><ellipse cx={x+4} cy={y} rx="4" ry="6"/></g>)}{face("#b98e74")}</svg>;
    case "cidade": return <svg {...A}><rect width="100" height="84" fill="#cdd2d6"/><g fill="#9aa3a8">{[6,22,40,62,80].map((x,i)=><rect key={i} x={x} y={30+(i%3)*8} width="12" height="54"/>)}</g>{face("#7a6450")}</svg>;
    case "abstrato": return <svg {...A}><rect width="100" height="84" fill="#efe7da"/><path d="M-5 50 Q30 20 55 50 T105 45" stroke="#c97b3f" strokeWidth="7" fill="none" opacity=".7"/><path d="M-5 64 Q40 40 70 66 T105 60" stroke="#7d94a8" strokeWidth="6" fill="none" opacity=".6"/>{face("#8a6e4b")}</svg>;
    case "colorido": return <svg {...A}><defs><linearGradient id="cl" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#e0517a"/><stop offset=".5" stopColor="#f0a02a"/><stop offset="1" stopColor="#3f9ad8"/></linearGradient></defs><rect width="100" height="84" fill="url(#cl)" opacity=".85"/>{face("#5a4630","#fff")}</svg>;
    case "recortes": return <svg {...A}><rect width="100" height="84" fill="#ece5d8"/>{[[6,8,18],[70,10,-10],[12,56,8],[64,58,12]].map(([x,y,r],i)=><rect key={i} x={x} y={y} width="26" height="14" fill="#fff" stroke="#bbb" transform={`rotate(${r} ${x} ${y})`}/>)}{face("#6f5a3e")}</svg>;
    case "minimal": return <svg {...A}><rect width="100" height="84" fill="#f6f3ec"/><g fill="none" stroke="#b0a68f" strokeWidth="1.4"><circle cx="50" cy="40" r="15"/><path d="M34 80 Q50 62 66 80"/></g></svg>;
    case "mediterraneo": return <svg {...A}><rect width="100" height="84" fill="#e9d9b8"/><rect y="58" width="100" height="26" fill="#5a8aa8" opacity=".6"/><circle cx="80" cy="20" r="9" fill="#f0c04a"/>{face("#c89a6a")}</svg>;
    case "biblioteca": return <svg {...A}><rect width="100" height="84" fill="#e7d8c4"/><g>{[6,20,34].map((y,i)=><g key={i}>{[10,22,34,46,58,70,82].map(x=><rect key={x} x={x} y={y} width="8" height="12" fill={["#8a4a3a","#3a5a6a","#7a6a3a"][(x+y)%3]}/>)}</g>)}</g>{face("#6f5a3e")}</svg>;
    case "mar": return <svg {...A}><rect width="100" height="84" fill="#bfe0e0"/><path d="M0 60 Q25 52 50 60 T100 60 V84 H0Z" fill="#5a9aa8"/><path d="M0 70 Q25 64 50 70 T100 70 V84 H0Z" fill="#3f7a8a"/>{face("#d8c4a8")}</svg>;
    case "campo": return <svg {...A}><rect width="100" height="84" fill="#dCe6c8"/><rect y="62" width="100" height="22" fill="#a8b878"/><circle cx="82" cy="18" r="8" fill="#f0c04a"/>{face("#b98e74")}</svg>;
    case "personalizado": return <svg {...A}><rect width="100" height="84" fill="#efe7da"/><text x="50" y="20" textAnchor="middle" fontSize="14" fill="#9a7b3f">✦</text>{face("#8a6e4b")}</svg>;
    default: return <svg {...A}><rect width="100" height="84" fill="#ece5d8"/>{face("#8a6e4b")}</svg>;
  }
}

// Miniaturas dos estilos artísticos (camada 2) — SVG gerado
function ArtStyleSample({ kind }) {
  const A = { width: "100%", height: 78, viewBox: "0 0 100 78", preserveAspectRatio: "xMidYMid slice", style: { display: "block", borderRadius: "6px 6px 0 0" } };
  const face = (fill) => <g><circle cx="50" cy="38" r="14" fill={fill} /><path d="M32 72 Q50 54 68 72 Z" fill={fill} /></g>;
  switch (kind) {
    case "realista": return <svg {...A}><defs><radialGradient id="re" cx="50%" cy="40%"><stop offset="0" stopColor="#e8cdb0"/><stop offset="1" stopColor="#9a7250"/></radialGradient></defs><rect width="100" height="78" fill="#cdbfa6"/><ellipse cx="50" cy="40" rx="22" ry="26" fill="url(#re)"/>{face("#b98e6a")}</svg>;
    case "abstrata": return <svg {...A}><rect width="100" height="78" fill="#efe7da"/><path d="M-5 45 Q30 15 55 45 T105 40" stroke="#c97b3f" strokeWidth="8" fill="none" opacity=".7"/><path d="M-5 60 Q40 35 70 62 T105 56" stroke="#7d94a8" strokeWidth="7" fill="none" opacity=".6"/><circle cx="52" cy="40" r="13" fill="#8a6e4b" opacity=".85"/></svg>;
    case "geometrica": return <svg {...A}><rect width="100" height="78" fill="#e7dcc4"/><g opacity=".88"><polygon points="50,12 66,40 50,40" fill="#c98a4e"/><polygon points="50,12 34,40 50,40" fill="#e0b07a"/><polygon points="34,40 66,40 50,68" fill="#9a7250"/><polygon points="30,30 44,52 18,52" fill="#7d94a8" opacity=".7"/></g></svg>;
    case "popart": return <svg {...A}><rect width="50" height="39" fill="#f6c026"/><rect x="50" width="50" height="39" fill="#e0517a"/><rect y="39" width="50" height="39" fill="#3f9ad8"/><rect x="50" y="39" width="50" height="39" fill="#5db06a"/>{face("#2b2620")}</svg>;
    case "street": return <svg {...A}><rect width="100" height="78" fill="#3a3a3c"/><path d="M0 56 L100 36" stroke="#e0517a" strokeWidth="9"/><path d="M0 28 L100 66" stroke="#f6c026" strokeWidth="6" opacity=".8"/>{face("#d8c4a8")}</svg>;
    case "colagem": return <svg {...A}><rect width="100" height="78" fill="#ece5d8"/><rect x="8" y="8" width="40" height="34" fill="#c9a87c" transform="rotate(-6 28 25)"/><rect x="52" y="28" width="38" height="42" fill="#9ab0a0" transform="rotate(5 71 49)"/>{face("#6f5a3e")}</svg>;
    default: return <svg {...A}><rect width="100" height="78" fill="#ece5d8"/>{face("#8a6e4b")}</svg>;
  }
}

// Galeria de inspirações — seleção de até 3
function InspiracoesGaleria({ selected, onChange }) {
  const [open, setOpen] = useState(false);
  const toggle = (id) => {
    if (selected.includes(id)) onChange(selected.filter((x) => x !== id));
    else if (selected.length < 3) onChange([...selected, id]);
  };
  return (
    <div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
        {selected.map((id) => {
          const g = GALERIA.find((x) => x.id === id);
          return <div key={id} style={{ ...S.thumb, width: 70, height: 70, overflow: "hidden" }}><ArtSample kind={g?.art} /></div>;
        })}
        <button className="ghost" type="button" onClick={() => setOpen(true)}>✦ Abrir galeria de inspirações</button>
        <span style={{ fontSize: 13, color: MUTE }}>{selected.length}/3 selecionadas</span>
      </div>

      {open && (
        <div style={S.modalBg} onClick={() => setOpen(false)}>
          <div style={S.modal} onClick={(e) => e.stopPropagation()}>
            <div style={S.modalHead}>
              <h3 style={{ ...S.h2, margin: 0 }}>Galeria de inspirações</h3>
              <button className="ghost sm2" onClick={() => setOpen(false)}>Fechar</button>
            </div>
            <p style={{ color: MUTE, fontSize: 14, margin: "0 0 16px" }}>Toque para selecionar até 3 que combinam com o que você sonha.</p>
            <div style={S.galeriaGrid}>
              {GALERIA.map((g) => (
                <button key={g.id} type="button" className={selected.includes(g.id) ? "gitem on" : "gitem"} onClick={() => toggle(g.id)}>
                  <ArtSample kind={g.art} />
                  {selected.includes(g.id) && <span style={S.gcheck}>✓</span>}
                </button>
              ))}
            </div>
            <button className="primary block" style={{ marginTop: 18 }} onClick={() => setOpen(false)}>Concluir seleção ({selected.length}/3)</button>
          </div>
        </div>
      )}
    </div>
  );
}

function ratioOf(orient) { return orient === "paisagem" ? "4 / 3" : orient === "quadrado" ? "1 / 1" : "3 / 4"; }

// A arte aplicada em 3 ambientes de parede diferentes
const ROOMS = [
  { id: "sala", name: "Sala", wall: "#e9e3d8", floor: "#cbb89a", scale: 0.52, x: "50%", y: "42%", sofa: true },
  { id: "destaque", name: "Em destaque", wall: "#dfd8cb", floor: null, scale: 0.66, x: "50%", y: "46%", sofa: false },
  { id: "quarto", name: "Quarto", wall: "#e4dccf", floor: "#bfa988", scale: 0.46, x: "50%", y: "40%", sofa: false, bed: true },
];
function RoomMockup({ tone, orientacao }) {
  return (
    <div style={S.roomGrid}>
      {ROOMS.map((r) => (
        <div key={r.id}>
          <div style={{ ...S.room, background: r.wall }}>
            {r.floor && <div style={{ ...S.roomFloor, background: r.floor }} />}
            {r.sofa && <div style={S.roomSofa} />}
            {r.bed && <div style={S.roomBed} />}
            <div style={{
              position: "absolute", left: r.x, top: r.y, transform: "translate(-50%,-50%)",
              height: `${r.scale * 100}%`, aspectRatio: ratioOf(orientacao),
              background: artGradient(tone), border: "4px solid #fff",
              boxShadow: "0 6px 16px rgba(0,0,0,.22)", borderRadius: 1,
            }} />
          </div>
          <p style={S.roomLabel}>{r.name}</p>
        </div>
      ))}
    </div>
  );
}

// Mostra as fotos agrupadas por sujeito; cai para fotos antigas se não houver sujeitos
function SubjectPhotos({ order, big }) {
  const subs = (order.sujeitos && order.sujeitos.length)
    ? order.sujeitos
    : [{ id: "legacy", quem: "", fotos: order.fotos || [], fotosSecundarias: order.fotosSecundarias || [] }];
  return (
    <div>
      {subs.map((s, i) => {
        const todas = [...(s.fotos || []), ...(s.fotosSecundarias || [])];
        if (todas.length === 0) return null;
        return (
          <div key={s.id} style={{ marginBottom: 12 }}>
            {(order.sujeitos && order.sujeitos.length > 1 || s.quem) && <p style={S.subjLabel}>{s.quem || `Pessoa ${i + 1}`}</p>}
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
              {todas.map((p, j) => <Thumb key={p.id} tone={p.tone} src={p.src} big={big && j === 0} />)}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function Frame({ fill, tone, src }) {
  return (
    <div style={S.frameWrap}>
      <div style={{ ...S.frameArt, background: src ? `center/cover no-repeat url(${src})` : artGradient(tone) }} />
      <svg style={S.frameSvg} viewBox="0 0 100 64" preserveAspectRatio="none">
        <rect x="3" y="3" width="94" height="58" fill="none" stroke={LINE} strokeWidth="2" />
        <rect x="3" y="3" width="94" height="58" fill="none" stroke={GOLD} strokeWidth="2" strokeDasharray="304" strokeDashoffset={304 * (1 - fill)} style={{ transition: "stroke-dashoffset .8s ease" }} />
      </svg>
    </div>
  );
}
function ProgressRail({ status }) {
  const order = ["recebido", "producao", "aprovacao", "finalizado"];
  const map = { recebido: 0, producao: 1, aprovacao: 2, ajustes: 2, finalizado: 3 };
  const cur = map[status];
  return (
    <div className="rail">
      {order.map((s, i) => (
        <div key={s} className="railstep">
          <span className={i <= cur ? "dot on" : "dot"}>{i < cur ? "✓" : i + 1}</span>
          <span className={i <= cur ? "railLbl on" : "railLbl"}>{STATUSES[s].label}</span>
          {i < order.length - 1 && <span className={i < cur ? "bar on" : "bar"} />}
        </div>
      ))}
    </div>
  );
}
function Stepper({ steps, step }) {
  return (
    <div className="rail" style={{ marginBottom: 22 }}>
      {steps.map((s, i) => (
        <div key={s} className="railstep">
          <span className={i <= step ? "dot on" : "dot"}>{i < step ? "✓" : i + 1}</span>
          <span className={i <= step ? "railLbl on" : "railLbl"}>{s}</span>
          {i < steps.length - 1 && <span className={i < step ? "bar on" : "bar"} />}
        </div>
      ))}
    </div>
  );
}
function StatusTag({ status, big }) {
  return <span className={`tag ${status}`} style={big ? { fontSize: 13, padding: "6px 14px" } : undefined}>{STATUSES[status].label}</span>;
}
function Field({ label, children }) { return <div style={{ marginBottom: 18 }}><label className="lbl">{label}</label>{children}</div>; }
function Detail({ k, v }) { return <div style={S.detailRow}><span style={S.detailK}>{k}</span><span style={S.detailV}>{v || "—"}</span></div>; }
function Thumb({ tone, src, ref_, big }) {
  const sz = big ? 88 : 64;
  return <div style={{ ...S.thumb, width: sz, height: sz, overflow: "hidden", background: src ? `center/cover no-repeat url(${src})` : artGradient(tone) }}>{ref_ && <span style={S.refBadge}>ref</span>}</div>;
}
function Empty({ t }) { return <span style={{ color: MUTE, fontSize: 13 }}>{t}</span>; }
function UploadOne({ label, value, onChange }) {
  const inputRef = React.useRef(null);
  const handle = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => onChange && onChange(reader.result);
    reader.readAsDataURL(file);
  };
  return (
    <div>
      <button type="button" className="uploadone" onClick={() => inputRef.current?.click()}
        style={value ? { borderStyle: "solid", padding: 0, height: 160, overflow: "hidden", background: `center/cover no-repeat url(${value})` } : undefined}>
        {!value && <><span style={{ fontSize: 18, color: GOLD }}>＋</span> {label}</>}
      </button>
      {value && <button type="button" className="ghost sm" style={{ marginTop: 6 }} onClick={() => onChange && onChange(null)}>Trocar imagem</button>}
      <input ref={inputRef} type="file" accept="image/*" style={{ display: "none" }} onChange={handle} />
    </div>
  );
}

function Chips({ options, value, onChange, freeText, freePlaceholder }) {
  const isCustom = value && !options.includes(value);
  return (
    <div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>{options.map((o) => <button key={o} className={value === o ? "chip on" : "chip"} onClick={() => onChange(o)}>{o}</button>)}</div>
      {freeText && <input className="inp" style={{ marginTop: 10 }} value={isCustom ? value : ""} onChange={(e) => onChange(e.target.value)} placeholder={freePlaceholder || "Ou escreva por extenso…"} />}
    </div>
  );
}
function Uploader({ items, max, onChange, hint, big }) {
  const ref = useRef();
  const add = (files) => {
    const arr = Array.from(files).slice(0, max - items.length);
    const readers = arr.map((file) => new Promise((res) => {
      const r = new FileReader();
      r.onload = () => res({ id: uid(), src: r.result, name: file.name });
      r.onerror = () => res({ id: uid(), src: null });
      r.readAsDataURL(file);
    }));
    Promise.all(readers).then((imgs) => onChange([...items, ...imgs]));
  };
  return (
    <div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
        {items.map((it) => {
          const sz = big && max === 1 ? 120 : 80;
          return (
            <div key={it.id} style={{ ...S.thumb, width: sz, height: sz, position: "relative", overflow: "hidden",
              background: it.src ? `center/cover no-repeat url(${it.src})` : artGradient(it.tone) }}>
              <button className="rm" onClick={() => onChange(items.filter((x) => x.id !== it.id))}>×</button>
            </div>
          );
        })}
        {items.length < max && (
          <button className={big && items.length === 0 ? "dropzone big" : "dropzone"} onClick={() => ref.current.click()}>
            <span style={{ fontSize: big && items.length === 0 ? 30 : 22, color: GOLD }}>＋</span>
            <span style={{ fontSize: 12, color: MUTE }}>{hint}</span>
          </button>
        )}
      </div>
      <input ref={ref} type="file" accept="image/*" multiple hidden onChange={(e) => add(e.target.files)} />
    </div>
  );
}

/* ---------------------------------- helpers ---------------------------------- */
function artGradient(tone = "#d8c9b4") {
  return `radial-gradient(120% 90% at 30% 20%, ${tone} 0%, ${shade(tone, -16)} 58%, ${shade(tone, -34)} 100%)`;
}
function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  const r = clamp((n >> 16) + amt), g = clamp(((n >> 8) & 255) + amt), b = clamp((n & 255) + amt);
  return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
}
const clamp = (v) => Math.max(0, Math.min(255, v));
function today() { return new Date().toLocaleDateString("pt-BR", { day: "numeric", month: "short", year: "numeric" }).replace(".", ""); }
function nameOf(list, id) { const x = list.find((e) => e.id === id); return x ? x.name : ""; }
function fmtPersonalidades(ids) { return (ids || []).map((id) => nameOf(PERSONALIDADES, id)).filter(Boolean).join(", "); }
function fmtFormato(o) {
  const orient = (ORIENTACOES.find((x) => x.id === o.orientacao) || {}).name || "";
  const medida = o.tamanho === "outro" ? (o.tamanhoOutro || "sob medida") : ((TAMANHOS[o.orientacao] || []).find((x) => x.id === o.tamanho) || {}).cm;
  return [orient, medida].filter(Boolean).join(" · ");
}
function fmtDate(iso) { if (!iso) return ""; const [y, m, d] = iso.split("-"); return `${d}/${m}/${y}`; }

/* ---------------------------------- styles ---------------------------------- */
const SERIF = "'Cormorant Garamond', Georgia, serif";
const S = {
  root: { minHeight: "100vh", background: PAPER, color: INK, fontFamily: "'Inter', system-ui, sans-serif" },
  header: { display: "flex", justifyContent: "space-between", alignItems: "center", padding: "18px 28px", borderBottom: `1px solid ${LINE}`, position: "sticky", top: 0, background: "rgba(251,250,247,.88)", backdropFilter: "blur(8px)", zIndex: 10 },
  brand: { display: "flex", alignItems: "baseline", gap: 10 },
  mark: { color: GOLD, fontSize: 18 },
  wordmark: { fontFamily: SERIF, fontSize: 26, fontWeight: 600, letterSpacing: ".02em" },
  tagline: { fontSize: 11, letterSpacing: ".22em", textTransform: "uppercase", color: "#b0a68f" },
  headRight: { display: "flex", alignItems: "center", gap: 14 },
  userPill: { fontSize: 13, color: MUTE },
  main: { maxWidth: 1080, margin: "0 auto", padding: "40px 28px 60px" },
  footer: { textAlign: "center", padding: "30px", fontSize: 12, color: "#b0a68f", borderTop: `1px solid ${LINE}` },

  eyebrow: { fontSize: 11, letterSpacing: ".24em", textTransform: "uppercase", color: GOLD, marginBottom: 10, fontWeight: 600 },
  h1: { fontFamily: SERIF, fontSize: 42, fontWeight: 500, lineHeight: 1.05, margin: 0, letterSpacing: "-.01em", color: INK },
  h2: { fontFamily: SERIF, fontSize: 25, fontWeight: 500, margin: "0 0 16px" },
  h3: { fontSize: 12, letterSpacing: ".14em", textTransform: "uppercase", color: "#b0a68f", margin: "22px 0 10px" },
  lede: { color: MUTE, fontSize: 16, lineHeight: 1.6, margin: "14px 0 26px" },

  adminRow: { marginTop: 18, paddingTop: 16, borderTop: `1px solid ${LINE}`, textAlign: "center" },
  dashHead: { display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 30, flexWrap: "wrap", gap: 16 },
  grid: { display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 22 },
  empty: { textAlign: "center", padding: "64px 20px", border: `1px dashed ${GOLD_SOFT}`, borderRadius: 10, background: "#fff" },

  cardTop: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 },
  orderNo: { fontFamily: SERIF, fontSize: 18, color: MUTE },
  cardPara: { fontSize: 16, margin: "2px 0 4px" },
  cardMeta: { fontSize: 13, color: "#b0a68f", marginBottom: 12 },

  card: { background: "#fff", border: `1px solid ${LINE}`, borderRadius: 8, padding: "26px 28px", marginBottom: 22 },
  fieldHint: { color: MUTE, marginBottom: 14, fontSize: 14 },
  microHint: { fontSize: 13, color: "#b0a68f", marginTop: 8 },
  wizardNav: { display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 24, paddingTop: 20, borderTop: `1px solid ${LINE}` },

  styleGrid: { display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(190px,1fr))", gap: 14 },
  artGrid: { display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px,1fr))", gap: 12 },
  artImg: { width: "100%", height: 110, objectFit: "cover", display: "block", borderRadius: "6px 6px 0 0" },
  modalBg: { position: "fixed", inset: 0, background: "rgba(31,27,22,.5)", display: "flex", alignItems: "center", justifyContent: "center", padding: 20, zIndex: 100 },
  modal: { background: "#fff", borderRadius: 12, padding: "24px 26px", maxWidth: 640, width: "100%", maxHeight: "85vh", overflowY: "auto" },
  modalHead: { display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 },
  galeriaGrid: { display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(120px,1fr))", gap: 10 },
  gcheck: { position: "absolute", top: 6, right: 6, width: 24, height: 24, borderRadius: "50%", background: GOLD, color: "#fff", display: "grid", placeItems: "center", fontWeight: 700, fontSize: 13 },
  swatch: { display: "flex", height: 64, borderRadius: 6, overflow: "hidden", marginBottom: 12 },
  tonDots: { display: "flex", gap: 3, marginRight: 4 },
  relRow: { display: "flex", flexDirection: "column", gap: 10 },
  subjectCard: { border: `1px solid ${LINE}`, borderRadius: 8, padding: "16px 18px", marginBottom: 14, background: PAPER },
  subjectHead: { display: "flex", alignItems: "center", gap: 12 },
  subjectNum: { width: 26, height: 26, borderRadius: "50%", background: GOLD, color: "#fff", display: "grid", placeItems: "center", fontSize: 13, fontWeight: 700, flex: "0 0 auto" },
  subjLabel: { fontSize: 12, letterSpacing: ".08em", textTransform: "uppercase", color: GOLD, margin: "0 0 7px", fontWeight: 600 },
  orientRow: { display: "flex", gap: 12, flexWrap: "wrap" },
  orientIconBox: { height: 44, display: "flex", alignItems: "center", justifyContent: "center" },
  orientShape: { display: "block", width: 30, background: GOLD_SOFT, borderRadius: 2 },
  orientName: { fontSize: 13, lineHeight: 1 },
  roomGrid: { display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 12 },
  room: { position: "relative", aspectRatio: "1 / 1", borderRadius: 8, overflow: "hidden", border: `1px solid ${LINE}` },
  roomFloor: { position: "absolute", left: 0, right: 0, bottom: 0, height: "26%" },
  roomSofa: { position: "absolute", left: "18%", right: "18%", bottom: "10%", height: "20%", backgroundColor: "#a08a6c", borderRadius: "10px 10px 4px 4px" },
  roomBed: { position: "absolute", left: "12%", right: "12%", bottom: "6%", height: "24%", background: "#c8b89a", borderRadius: "8px 8px 0 0" },
  roomLabel: { textAlign: "center", fontSize: 12, color: MUTE, marginTop: 7 },

  frameWrap: { position: "relative", aspectRatio: "100/64", overflow: "hidden", background: "#fff" },
  frameArt: { position: "absolute", inset: 9 },
  frameSvg: { position: "absolute", inset: 0, width: "100%", height: "100%" },

  detailHead: { display: "flex", justifyContent: "space-between", alignItems: "flex-end", margin: "10px 0 24px", flexWrap: "wrap", gap: 14 },
  statusHint: { color: MUTE, fontStyle: "italic", margin: "14px 0 24px", fontFamily: SERIF, fontSize: 19 },

  versionGrid: { display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 16 },
  bigArt: { borderRadius: 4, height: 230, position: "relative", border: `1px solid ${LINE}` },
  check: { position: "absolute", top: 12, right: 12, width: 30, height: 30, borderRadius: "50%", background: GOLD, color: "#fff", display: "grid", placeItems: "center", fontWeight: 700 },

  divider: { height: 1, background: LINE, margin: "20px 0" },
  quote: { borderLeft: `3px solid ${GOLD}`, paddingLeft: 16, margin: "12px 0 0", color: "#6a6155", fontStyle: "italic" },
  msg: { padding: "12px 14px", borderRadius: 6, background: "#faf6ec", marginBottom: 10, fontSize: 14, lineHeight: 1.5 },
  msgHead: { display: "flex", justifyContent: "space-between", fontSize: 12, fontWeight: 600, color: GOLD },

  detailRow: { display: "flex", gap: 16, padding: "8px 0", borderBottom: `1px solid ${PAPER}` },
  detailK: { flex: "0 0 130px", fontSize: 12, letterSpacing: ".08em", textTransform: "uppercase", color: "#b0a68f", paddingTop: 2 },
  detailV: { flex: 1, fontSize: 15, lineHeight: 1.55 },
  thumb: { width: 64, height: 64, borderRadius: 4, border: `1px solid ${LINE}`, position: "relative" },
  refBadge: { position: "absolute", bottom: 4, right: 4, fontSize: 9, background: "rgba(31,27,22,.6)", color: "#fff", padding: "1px 5px", borderRadius: 3, letterSpacing: ".05em" },

  table: { width: "100%", borderCollapse: "collapse", marginTop: 20, fontSize: 14 },
  adminCols: { display: "grid", gridTemplateColumns: "1.05fr 1fr", gap: 22, alignItems: "start" },
};

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Inter:wght@400;500;600;700&display=swap');
* { box-sizing: border-box; }
body { margin: 0; }
em { font-style: italic; color: ${GOLD}; }
.reveal { animation: rise .5s ease both; }
@keyframes rise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } }

.lbl { display: block; font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #b0a68f; margin: 0 0 7px; }
.inp { width: 100%; padding: 12px 14px; border: 1px solid ${GOLD_SOFT}; border-radius: 6px; font-size: 15px; font-family: inherit; background: #fff; color: ${INK}; transition: border-color .2s, box-shadow .2s; }
.inp:focus { outline: none; border-color: ${GOLD}; box-shadow: 0 0 0 3px rgba(154,123,63,.13); }
.ta { resize: vertical; min-height: 88px; line-height: 1.5; }
.ta.tall { min-height: 120px; }

button { cursor: pointer; font-family: inherit; }
.primary { background: ${INK}; color: #fff; border: none; padding: 13px 26px; border-radius: 6px; font-size: 14px; font-weight: 500; letter-spacing: .01em; transition: transform .15s, background .2s; }
.primary:hover { transform: translateY(-1px); background: #000; }
.primary:disabled { opacity: .38; cursor: not-allowed; transform: none; }
.primary.block { width: 100%; }
.primary.lg { padding: 15px 32px; font-size: 15px; }
.ghost { background: transparent; color: ${INK}; border: 1px solid ${GOLD_SOFT}; padding: 11px 20px; border-radius: 6px; font-size: 14px; transition: border-color .2s, color .2s; }
.ghost:hover { border-color: ${GOLD}; color: ${GOLD}; }
.ghost.block { width: 100%; }
.ghost:disabled { opacity: .4; cursor: not-allowed; }
.ghost.sm { padding: 6px 0; border: none; color: ${MUTE}; margin-bottom: 14px; }
.ghost.sm:hover { color: ${GOLD}; }
.ghost.sm2 { padding: 7px 14px; font-size: 13px; }
.block { margin-top: 8px; }
.google { width: 100%; margin-top: 12px; background: #fff; border: 1px solid ${GOLD_SOFT}; padding: 12px; border-radius: 6px; font-size: 14px; display: flex; gap: 10px; align-items: center; justify-content: center; color: ${INK}; }
.google:hover { border-color: ${GOLD}; }
.google b { color: ${GOLD}; font-size: 16px; }
.primary.block, .ghost.block { margin-top: 8px; }
.link { color: ${GOLD}; font-size: 13px; font-weight: 600; }

.tabs { display: flex; gap: 6px; margin: 0 0 20px; background: ${PAPER}; padding: 4px; border-radius: 8px; border: 1px solid ${LINE}; }
.tab { flex: 1; padding: 9px; border: none; background: transparent; border-radius: 5px; font-size: 13px; color: ${MUTE}; font-weight: 500; }
.tab.on { background: #fff; color: ${GOLD}; box-shadow: 0 1px 3px rgba(0,0,0,.06); }

.ordercard { text-align: left; background: #fff; border: 1px solid ${LINE}; border-radius: 8px; overflow: hidden; padding: 0; transition: transform .2s, box-shadow .2s; display: block; }
.ordercard:hover { transform: translateY(-3px); box-shadow: 0 14px 34px rgba(31,27,22,.09); }

.tag { display: inline-block; font-size: 11px; letter-spacing: .03em; padding: 4px 11px; border-radius: 20px; font-weight: 600; white-space: nowrap; }
.tag.recebido { background: #f0ece2; color: #7a746b; }
.tag.producao { background: #fdeccb; color: #9a6b12; }
.tag.aprovacao { background: #f6ecd8; color: ${GOLD}; }
.tag.ajustes { background: #f3e6e0; color: #8a6a55; }
.tag.finalizado { background: #e7efe6; color: #5d7a5a; }

.chip { padding: 9px 16px; border: 1px solid ${GOLD_SOFT}; background: #fff; border-radius: 22px; font-size: 13px; color: #5c564c; transition: all .15s; font-weight: 500; }
.chip:hover { border-color: ${GOLD}; }
.chip.on { background: ${INK}; color: #fff; border-color: ${INK}; }

.tonchip { display: flex; align-items: center; gap: 4px; padding: 8px 14px; border: 1px solid ${GOLD_SOFT}; background: #fff; border-radius: 22px; font-size: 13px; color: #5c564c; font-weight: 500; }
.tonchip:hover { border-color: ${GOLD}; }
.tonchip.on { background: #faf4e6; border-color: ${GOLD}; color: ${GOLD}; }
.tonchip i { width: 11px; height: 11px; border-radius: 50%; display: inline-block; }

.orient { display: flex; flex-direction: column; align-items: center; justify-content: space-between; gap: 8px; width: 96px; height: 96px; padding: 12px; border: 1px solid ${GOLD_SOFT}; background: #fff; border-radius: 8px; color: #5c564c; font-weight: 500; }
.orient:hover { border-color: ${GOLD}; }
.orient.on { border-color: ${GOLD}; box-shadow: 0 0 0 2px rgba(154,123,63,.28); }
.orient.on span span { background: ${GOLD}; }
.sizechip { display: flex; flex-direction: column; align-items: flex-start; gap: 1px; padding: 10px 16px; border: 1px solid ${GOLD_SOFT}; background: #fff; border-radius: 8px; color: #5c564c; min-width: 96px; }
.sizechip:hover { border-color: ${GOLD}; }
.sizechip.on { border-color: ${GOLD}; box-shadow: 0 0 0 2px rgba(154,123,63,.28); }
.sizechip strong { font-size: 14px; }
.sizechip span { font-size: 12px; color: ${MUTE}; }

.stylecard { text-align: left; display: flex; flex-direction: column; gap: 4px; background: #fff; border: 1px solid ${GOLD_SOFT}; border-radius: 8px; padding: 12px; transition: all .18s; }
.stylecard:hover { border-color: ${GOLD}; transform: translateY(-2px); }
.stylecard.on { border-color: ${GOLD}; box-shadow: 0 0 0 2px rgba(154,123,63,.3); }

.artcard { text-align: left; display: flex; flex-direction: column; background: #fff; border: 1px solid ${GOLD_SOFT}; border-radius: 8px; overflow: hidden; transition: all .18s; padding: 0; }
.artcard:hover { border-color: ${GOLD}; transform: translateY(-2px); box-shadow: 0 8px 20px rgba(31,27,22,.08); }
.artcard.on { border-color: ${GOLD}; box-shadow: 0 0 0 2px rgba(154,123,63,.32); }
.artcard strong { font-family: ${SERIF}; font-size: 16px; font-weight: 600; padding: 10px 12px 0; }
.artcard span { font-size: 12px; color: ${MUTE}; line-height: 1.35; padding: 2px 12px 12px; }
.artcard.sm strong { font-size: 14px; padding: 8px 10px 8px; }
.artcard.sm span { display: none; }

.painttype { text-align: left; display: flex; flex-direction: column; background: #fff; border: 1px solid ${GOLD_SOFT}; border-radius: 8px; overflow: hidden; transition: all .18s; padding: 0; }
.painttype:hover { border-color: ${GOLD}; transform: translateY(-2px); box-shadow: 0 8px 20px rgba(31,27,22,.08); }
.painttype.on { border-color: ${GOLD}; box-shadow: 0 0 0 2px rgba(154,123,63,.32); }
.painttype .ptbody { position: relative; padding: 10px 12px 12px; }
.painttype .ptbody strong { display: block; font-family: ${SERIF}; font-size: 16px; font-weight: 600; }
.painttype .ptbody span { display: block; font-size: 12px; color: ${MUTE}; line-height: 1.3; margin-top: 1px; }
.painttype .ptbrush { height: 0; margin-top: 0; border-radius: 3px; background-size: cover; background-position: center; opacity: 0; transition: height .35s ease, margin-top .35s ease, opacity .3s ease; }
.painttype:hover .ptbrush { height: 14px; margin-top: 8px; opacity: 1; }

.gitem { position: relative; border: 2px solid ${LINE}; border-radius: 8px; overflow: hidden; padding: 0; cursor: pointer; transition: border-color .15s; background: #fff; }
.gitem:hover { border-color: ${GOLD_SOFT}; }
.gitem.on { border-color: ${GOLD}; box-shadow: 0 0 0 2px rgba(154,123,63,.3); }
.stylecard strong { font-family: ${SERIF}; font-size: 19px; font-weight: 600; }
.stylecard span { font-size: 12.5px; color: ${MUTE}; line-height: 1.4; }

.version { text-align: left; display: flex; flex-direction: column; gap: 8px; background: #fff; border: 1px solid ${GOLD_SOFT}; border-radius: 8px; padding: 12px; transition: all .18s; }
.version:hover { border-color: ${GOLD}; }
.version.on { border-color: ${GOLD}; box-shadow: 0 0 0 2px rgba(154,123,63,.32); }
.version strong { font-family: ${SERIF}; font-size: 19px; }

.dropzone { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; width: 104px; height: 104px; border: 1.5px dashed ${GOLD_SOFT}; border-radius: 8px; background: ${PAPER}; transition: border-color .2s, background .2s; }
.dropzone.big { width: 100%; height: 150px; }
.dropzone:hover { border-color: ${GOLD}; background: #fff; }
.rm { position: absolute; top: -7px; right: -7px; width: 20px; height: 20px; border-radius: 50%; background: ${INK}; color: #fff; border: none; font-size: 13px; line-height: 1; display: grid; place-items: center; }
.uploadone { width: 100%; margin-top: 8px; display: flex; align-items: center; gap: 8px; justify-content: center; padding: 14px; border: 1.5px dashed ${GOLD_SOFT}; border-radius: 8px; background: ${PAPER}; color: ${MUTE}; font-size: 13px; transition: border-color .2s; }
.uploadone:hover { border-color: ${GOLD}; }

.rail { display: flex; align-items: center; flex-wrap: wrap; }
.railstep { display: flex; align-items: center; }
.dot { width: 28px; height: 28px; border-radius: 50%; border: 1.5px solid ${GOLD_SOFT}; color: #b0a68f; display: grid; place-items: center; font-size: 13px; flex: 0 0 auto; font-weight: 600; }
.dot.on { background: ${GOLD}; border-color: ${GOLD}; color: #fff; }
.railLbl { font-size: 12px; color: #b0a68f; margin: 0 14px 0 8px; white-space: nowrap; }
.railLbl.on { color: ${INK}; font-weight: 500; }
.bar { width: 26px; height: 1.5px; background: ${GOLD_SOFT}; margin-right: 14px; }
.bar.on { background: ${GOLD}; }

.filters { display: flex; gap: 8px; flex-wrap: wrap; margin: 22px 0 4px; }
.filt { padding: 8px 14px; border: 1px solid ${GOLD_SOFT}; background: #fff; border-radius: 22px; font-size: 13px; color: #5c564c; display: flex; gap: 7px; align-items: center; font-weight: 500; }
.filt:hover { border-color: ${GOLD}; }
.filt.on { background: ${INK}; color: #fff; border-color: ${INK}; }
.filt i { font-style: normal; opacity: .65; font-size: 11px; }

table th { text-align: left; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: #b0a68f; font-weight: 600; padding: 10px 12px; border-bottom: 1px solid ${LINE}; }
.trow td { padding: 14px 12px; border-bottom: 1px solid ${PAPER}; }
.trow:hover { background: ${PAPER}; }

@media (max-width: 880px) { [style*="grid-template-columns: 1.05fr 1fr"] { grid-template-columns: 1fr !important; } }
@media (max-width: 760px) { h1 { font-size: 34px !important; } .railLbl { display: none; } .bar { width: 16px; } }
@media (max-width: 640px) {
  table, thead, tbody, th, td, tr { display: block; }
  thead { display: none; }
  .trow { border: 1px solid ${LINE}; border-radius: 8px; margin-bottom: 12px; padding: 6px 10px; }
  .trow td { border: none; padding: 6px 4px; display: flex; justify-content: space-between; }
}
`;
